import * as Effect from "effect/Effect"
const action = <A>(name: string, body: A): A => body
export effect function bootstrap() {
  const built = try Effect.orDie(Effect.try({ try: () => action("bootstrap", effect { const n: number = try Effect.succeed(1); return n + 1 }), catch: (e) => e }))
  const result: number = try built
  return result
}
